mapper.update:
UPDATE `notification_grants` SET `boundBizType`='ORDER',`boundBizId`=#{orderId},`updatedAt`=#{updatedAt}
WHERE `_id`=#{id} AND `openid`=#{openid} AND `templateKey`=#{templateKey}
  AND `subscriptionRole`='BUYER' AND `scene`='ORDER_SUBMIT' AND `status`='AVAILABLE' AND `boundBizId`=''

UPDATE `notification_grants` SET `status`='SENDING',`updatedAt`=#{grant.updatedAt}
WHERE `_id`=#{grant.id} AND `openid`=#{grant.openid} AND `templateKey`=#{grant.templateKey}
  AND `subscriptionRole`=#{grant.subscriptionRole} AND `status`='AVAILABLE'

  AND `scene`='ORDER_SUBMIT' AND `boundBizType`='ORDER' AND `boundBizId`=#{orderId}
  AND `scene`<>'ORDER_SUBMIT' AND `boundBizId`=''
